SELECT ?p ?label ?s ?tsid WHERE {
  ?p a brick:ElectricPowerSensor .
  ?p ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?p rdfs:label ?label }
}

SELECT DISTINCT ?cls WHERE {
  ?p a ?cls .
  FILTER (str(?cls) LIKE "%Sensor%")
}

SELECT ?cls (COUNT(*) AS ?n) WHERE {
  ?p a ?cls .
} GROUP BY ?cls

SELECT ?p ?zone ?zlabel ?tsid WHERE {
  ?p a brick:Electric_Power_Sensor .
  ?p ref:hasTimeseriesId ?tsid .
  ?p brick:hasParentLocation ?zone .
  OPTIONAL { ?zone rdfs:label ?zlabel }
}

SELECT ?p ?pobj WHERE {
  ?p a brick:Electric_Power_Sensor .
  ?p ref:hasTimeseriesId ?pobj .
} LIMIT 5

